(async()=>{const root=document.querySelector('#inquiries');try{const r=await fetch('/api/admin/inquiries');const data=await r.json();if(!r.ok)throw Error(data.error||'Bitte als Shop-Administrator anmelden.');root.replaceChildren();if(!data.inquiries.length)root.textContent='Noch keine Anpassungsanfragen.';for(const q of data.inquiries){const section=document.createElement('section');section.className='panel';for(const [label,value]of [['Eingang',new Date(q.created_at).toLocaleString('de-DE')],['Referenz',q.id],['Name',q.name],['E-Mail',q.email],['Produkt',q.product],['System',q.system],['Nachricht',q.message]]){const h=document.createElement('strong'),p=document.createElement('pre');h.textContent=label;p.textContent=value;section.append(h,p);}root.append(section);}}catch(e){root.textContent=e.message;const a=document.createElement('a');a.href='/#login';a.textContent=' Zum Betreiberkonto';root.append(a);}})();